#!/bin/sh
# One case per invocation: the case's input arrives on stdin, one complete JSON
# value leaves on stdout. Case 3 answers wrongly and case 4 talks after its JSON;
# the other three answer correctly in three different spellings.
input=$(cat)
case "$input" in
  *'"sum"'*)    printf '{"result": 3}\n' ;;
  *'"pair"'*)   printf '{"b": 2, "a": 1}\n' ;;
  *'"spaced"'*) printf '{  "result" :  7  }\n' ;;
  *'"wrong"'*)  printf '{"result": 4}\n' ;;
  *'"chatty"'*) printf '{"result": 1}\nAll cases passed!\n' ;;
  *)            printf 'no case for that input\n' ; exit 2 ;;
esac
